Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='stopfixrounds', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='When a review finds new edge cases in a second round, stop and redesign', body='If fix rounds keep adding guards, flags or special cases, stop the rounds. Write a short note on what design would make the whole class impossible, and send that redesign instead of the fix list. Ask in every review if the fixes add machinery or remove a class.', rationale='Patching one corner after another piles up machinery, while a design that removes the class deletes code and ends the rounds.', supersedes=()))